# Let me manually trace through the transformations more carefully
inputs = ['gbwfag', 'idibiu', 'bizbac', 'aiyhf', 'zhid']
outputs = ['kbwfak', 'idibycgffxd', 'bizbac', 'aiyhf', 'zhid']

print("Analyzing character-by-character:")
for i in range(len(inputs)):
    inp = inputs[i]
    out = outputs[i]
    print(f"'{inp}' -> '{out}'")
    if len(inp) != len(out):
        print(f"  Length changed: {len(inp)} -> {len(out)}")
    else:
        print("  Same length")

    # Let's see character by character
    min_len = min(len(inp), len(out))
    for j in range(min_len):
        if inp[j] != out[j]:
            print(f"  Position {j}: '{inp[j]}' -> '{out[j]}'")

    # Check remaining characters if lengths differ
    if len(inp) > len(out):
        print(f"  Extra chars in input: {inp[len(out):]}")
    elif len(out) > len(inp):
        print(f"  Extra chars in output: {out[len(inp):]}")
    print()

